+        assert.equal(dedup.issueOfRunName('teammate: issues #10401 '), 10401);
+        assert.notEqual(dedup.issueOfRunName('teammate: issues #10401 '), 1040);
+        assert.equal(dedup.issueOfRunName('▶ dev (SM) · gh-10401'), 10401);
