+            reason: 'duplicate',
+            audit: '⏭️ teammate dedup (gh-1065): dropped ' + String(input.action || 'issues') +
+                ' event on #' + issue + ' (leg \'' + (derived.leg || 'any') + '\') — ' +
+                owner + ' for the same issue+leg is ' + state +
+                ' within the dedup window; this trigger is a duplicate'
