+    return {
+        proceed: true,
+        reason: 'first-trigger',
+        audit: 'teammate dedup (gh-1065): no in-flight or freshly-completed run for #' +
+            issue + ' (leg \'' + (derived.leg || 'any') + '\') — proceeding'
