+        if (after === '' || after < '0' || after > '9') return parseInt(m[1], 10);
+        m = re.exec(name);
+    }
+    var gh = /(?:^|[^0-9a-zA-Z])gh-(\d+)/g;
+    m = gh.exec(name);
+    while (m) {
+        var afterGh = name.charAt(m.index + m[0].length);
+        if (afterGh === '' || afterGh < '0' || afterGh > '9') return parseInt(m[1], 10);
+        m = gh.exec(name);
