+        name: opts.name || ('teammate: issues #' + ISSUE + ' '),
+        status: status,
+        path: opts.path || LEG_PATH,
+        created_at: opts.createdAt || FIVE_MIN_AGO,
+        updated_at: opts.updatedAt || FIVE_MIN_AGO
