+}
+
+function selfRun(runNumber, opts) {
+    opts = opts || {};
+    return {
+        id: opts.id !== undefined ? opts.id : 800000 + runNumber,
+        runNumber: runNumber,
+        createdAt: opts.createdAt || NOW_MS
